const map = new Map();
map.set("b", 2);
map.set("a", 1);
map.set("d", 4);
map.set("c", 3);

console.log(...map.entries()) // [['b', 2], ['a', 1], ['d', 4], ['c', 3]]
console.log(...map.keys())    // b a d c
console.log(...map.values())  // 2 1 4 3

const set = new Set();
set.add("a");
set.add("d");
set.add("c");
set.add("b");

console.log(...set.values()); // a d c b
